import pytest
from mesh_config import compile_route_profile, validate_headers

def test_case_1():
    base = {
        "prefix": "/api",
        "matchers": {
            "headers": {
                "X-Tenant-Id": "tenant-123",
                "Authorization": "Bearer token",
                "X-Trace-Id": "trace-456"
            }
        }
    }
    env = {
        "matchers": {
            "headers": {
                "Authorization": "Bearer new-token"
            }
        }
    }

    # Test that headers are properly preserved
    headers = validate_headers(base, env)
    expected = ['X-Tenant-Id', 'Authorization', 'X-Trace-Id']
    assert headers == expected

    # Test full profile compilation
    prof = compile_route_profile("mesh-1", base, env)
    assert prof["mesh_id"] == "mesh-1"
    assert prof["prefix"] == "/api"
    assert "Authorization" in prof["rules"]["matchers"]["headers"]
    assert "X-Tenant-Id" in prof["rules"]["matchers"]["headers"]
    assert "X-Trace-Id" in prof["rules"]["matchers"]["headers"]
